/* Optional demonstration fixtures; never persisted. Reload returns to saved user state. */
const fixtureBar = document.createElement('details'); fixtureBar.className = 'bloom-preview-controls'; fixtureBar.innerHTML = '<summary>Charm & cover mockup states · preview only</summary><p>Sample shelves never change your saved progress. Reload to return to saved state.</p><button data-preview="empty">Empty shelf</button><button data-preview="starter">First three charms</button><button data-preview="regular">Regular user</button><button data-preview="all">Full shelf</button><button data-preview="congrats">Congratulations</button><button data-preview="cover">Choose cover</button><button data-preview="reload">Return to saved state</button>'; $('.demo').after(fixtureBar);
window.setCharmPreview = function (name) { if (name === 'reload') { location.reload(); return } if (name === 'cover') { questModal(); return } demoFixture = true; previewFixture = true; garden = Bloom.pause(garden, Date.now()); R = Charms.fresh(); if (name !== 'empty') { let counts = name === 'regular' ? { tasks: 12, quests: 1, days: 2, flowers: 0 } : name === 'all' ? { tasks: 250, quests: 30, days: 90, flowers: 30 } : { tasks: 5, quests: 1, days: 1, flowers: 0 }; for (const [key, n] of Object.entries(counts)) R[key] = Array.from({ length: n }, (_, i) => `sample-${key}-${i}`); R = Charms.evaluate(R, Date.now()); } R.pending = []; go(name === 'regular' ? 'discover' : 'collection'); if (name === 'congrats') { modal(`<div class="congrats"><h2>A little magic, earned!</h2>${charmArt('potion')}<h3>Something Magical</h3><p>You finished your first quest.</p><p>Added to your charms shelf.</p><button class="primary" data-action="cancel">Lovely!</button></div>`); $('#dialog').className = 'congrats-modal'; } };
fixtureBar.addEventListener('click', e => { const name = e.target.dataset.preview; if (name) setCharmPreview(name) });
